{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "(1) Study design: All included studies were RCTs; (2) Participants: All patients aged ≥ 18 years diagnosed with heart failure who meeting the diagnostic criteria and classified as NYHA functional class II-IV ...; (3) Interventions: The experimental group received conventional Western medicine ... supplemented with plant extracts. The control group received only conventional Western medicine; (4) Outcome measures: At least one of the following was assessed: Number of patients with improved NYHA classification, LVEF, 6MWT, or QoL.",
      "reason": "Study design, participants, interventions/comparator, and outcomes are clearly specified, but no settings or minimum follow-up requirements are reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "It should be noted that this search was restricted to published literature.",
      "reason": "Publication status (published literature only) is indicated, but no dissemination year limits or language restrictions are specified in the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_11",
      "quote": "(3) Literature with incomplete data or inability to obtain full text;",
      "reason": "Exclusion for 'incomplete data' is mentioned, but the review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Fifteen herbal extracts were compared, including Astragalus extract (6 studies) ... The primary outcomes assessed included Number of patients with improved NYHA classification, LVEF, 6MWT, or QoL. ... Twenty studies involving 13 interventions were included for Number of patients with improved NYHA classification",
      "reason": "The synthesis groups (individual plant extracts vs conventional treatment) are specified and linked to each outcome/comparison defined in the review objectives, with separate networks per outcome."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationales are provided for restrictions such as excluding non-RCTs, adults only, or published literature only."
    }
  ],
  "confidence": 88
}

